(function(){window.Swiper=class{constructor(selector,options={}){this.el=typeof selector==='string'?document.querySelector(selector):selector;if(!this.el)return;this.options=options;this.index=0;this.slides=[...this.el.children];this.wrapper=document.createElement('div');this.wrapper.className='swiper-wrapper';this.slides.forEach(s=>{s.classList.add('swiper-slide');this.wrapper.append(s)});this.el.append(this.wrapper);this.el.classList.add('swiper','is-swiper');this.el.style.setProperty('--swiper-size',options.slidesPerView===1?'100%':(100/(Number(options.slidesPerView)||1.15))+'%');this.nav=document.createElement('div');this.nav.className='swiper-nav';this.prev=document.createElement('button');this.next=document.createElement('button');this.prev.type=this.next.type='button';this.prev.innerHTML='<span class="ph ph-caret-left" aria-hidden="true"></span>';this.next.innerHTML='<span class="ph ph-caret-right" aria-hidden="true"></span>';this.prev.setAttribute('aria-label','Previous slide');this.next.setAttribute('aria-label','Next slide');this.nav.append(this.prev,this.next);this.el.after(this.nav);this.prev.onclick=()=>this.slideTo(this.index-1);this.next.onclick=()=>this.slideTo(this.index+1);this.update()}slideTo(i){this.index=Math.max(0,Math.min(this.slides.length-1,i));const width=this.slides[0]?.getBoundingClientRect().width||0;const gap=parseFloat(getComputedStyle(this.wrapper).gap)||0;this.wrapper.style.transform=`translateX(-${this.index*(width+gap)}px)`;this.update()}update(){this.prev.disabled=this.index===0;this.next.disabled=this.index>=this.slides.length-1}}})();
